package mod.cdv.tnpc.tactical;
import fixture.*;import java.util.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.EquipmentSlot;import mod.cdv.tnpc.entity.AutoGunOperator;import net.minecraft.core.BlockPos;import dev.zomboid.firstaid.*;import dev.zomboid.clans.Companions16;import me.danialisntcool.factionfriction.data.FactionManager;
public class JobChecks{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static AutoGunOperator npc(World w)throws Exception{AutoGunOperator n=new AutoGunOperator(w);Social.init(n);n.tag.putInt("soc_kind",2);return n;}static long amount(AutoGunOperator n,String id){return n.bag.stream().filter(s->s.id.equals(id)).mapToLong(s->s.count).sum();}
 public static void main(String[]args)throws Exception{
  World w=new World();AutoGunOperator helper=npc(w);Player patient=new Player(w);patient.x=1;AidChecks.Model model=new AidChecks.Model();Assist.models.put(patient,model);Social.Memory m=Social.mem(helper);NpcMedicine.tick(helper,m,0);ok(m.patient==patient&&m.medicalUntil==160,"passive starts actual eight-second CPR without defib");w.now=80;NpcMedicine.tick(helper,m,80);ok(patient.wakes==0,"no premature resuscitation");w.now=160;NpcMedicine.tick(helper,m,160);ok(patient.wakes==1&&model.normal==1&&m.patient==null,"completed NPC CPR wakes real First Aid model");
  World d=new World();AutoGunOperator medic=npc(d);Player down=new Player(d);down.x=1;AidChecks.Model advanced=new AidChecks.Model();Assist.models.put(down,advanced);medic.bag.add(new ItemStack("firstaid:defibrillator",1));Social.Memory dm=Social.mem(medic);NpcMedicine.tick(medic,dm,0);ok(dm.medicalUntil==60,"NPC-owned defib shortens rescue to three seconds");d.now=60;NpcMedicine.tick(medic,dm,60);ok(down.wakes==1&&advanced.defib==1,"NPC defib uses native advanced rescue");ok(medic.bag.get(0).damage==1,"one charge consumed from NPC defib, not player inventory");
  World h=new World();AutoGunOperator wounded=npc(h);wounded.hp=10;wounded.tag.putInt("np15_parts",1);Player healer=new Player(h);healer.x=1;ItemStack bandages=new ItemStack("firstaid:bandage",2);healer.setItemSlot(EquipmentSlot.MAINHAND,bandages);ok(NpcMedicine.playerTreat(wounded,healer),"non-faction player can start treatment");Social.Memory hm=Social.mem(wounded);NpcMedicine.tick(wounded,hm,0);h.now=60;NpcMedicine.tick(wounded,hm,60);ok(wounded.hp==15&&bandages.count==1,"successful treatment consumes exactly one held bandage");ok(Social.trust(wounded,healer)>0&&Social.rep(healer)>0,"healing improves trust and reputation");
  World healWorld=new World();AutoGunOperator npcMedic=npc(healWorld);Player hurt=new Player(healWorld);hurt.x=1;AidChecks.Model injury=new AidChecks.Model();injury.criticalConditionActive=false;Assist.models.put(hurt,injury);npcMedic.bag.add(new ItemStack("firstaid:bandage",2));Social.Memory med=Social.mem(npcMedic);NpcMedicine.tick(npcMedic,med,0);healWorld.now=60;NpcMedicine.tick(npcMedic,med,60);ok(NpcAid7.missing(hurt)==75&&amount(npcMedic,"firstaid:bandage")==1,"NPC heals player First Aid parts and consumes its own bandage");
  World group=new World();AutoGunOperator nurse=npc(group),injured=npc(group);injured.x=1;injured.hp=10;nurse.bag.add(new ItemStack("firstaid:bandage",1));Social.Memory nm=Social.mem(nurse);NpcMedicine.tick(nurse,nm,0);ok(nm.patient==injured&&nm.patientNpc,"friendly NPCs preserve mutual medical aid");group.now=60;NpcMedicine.tick(nurse,nm,60);ok(injured.hp==15&&amount(nurse,"firstaid:bandage")==0,"NPC-to-NPC treatment consumes one real bandage");
  World c=new World();AutoGunOperator cook=npc(c);BlockPos furnace=new BlockPos(0,0,0);Storage oven=new Storage();c.blocks.put(furnace,"minecraft:furnace");c.storage.put(furnace,oven);cook.bag.add(new ItemStack("minecraft:beef",4));cook.bag.add(new ItemStack("minecraft:coal",2));Social.Memory cm=Social.mem(cook);cm.work=furnace;cm.workKind="cook";Tasks.cook(cook,cm,0);ok(oven.getItem(0).id.equals("minecraft:beef")&&oven.getItem(0).count==1,"raw ingredient placed in real furnace input");ok(oven.getItem(1).id.equals("minecraft:coal")&&amount(cook,"minecraft:coal")==1,"cooking transfers actual fuel");ok(amount(cook,"minecraft:cooked_beef")==0&&amount(cook,"minecraft:beef")==3,"no instant cooked output or free ingredients");oven.setItem(0,ItemStack.EMPTY);oven.setItem(2,new ItemStack("minecraft:cooked_beef",1));Tasks.cook(cook,cm,200);ok(amount(cook,"minecraft:cooked_beef")==1&&oven.getItem(2).isEmpty(),"only collects output that the furnace actually produced");
  oven.tag.putBoolean("QuietlyPlayerPlaced",true);long before=amount(cook,"minecraft:beef");Tasks.cook(cook,cm,400);ok(amount(cook,"minecraft:beef")==before,"wild NPC respects protected player-placed storage");
  World l=new World();AutoGunOperator scavenger=npc(l);Storage barrel=new Storage();BlockPos box=new BlockPos(0,0,0);l.blocks.put(box,"minecraft:barrel");l.storage.put(box,barrel);barrel.setItem(0,new ItemStack("minecraft:coal",3));barrel.setItem(1,new ItemStack("minecraft:cobblestone",20));Social.Memory lm=Social.mem(scavenger);lm.work=box;l.rayBlocked=true;Tasks.loot(scavenger,lm,0);ok(amount(scavenger,"minecraft:coal")==0&&barrel.getItem(0).count==3,"cannot loot container through a wall");l.rayBlocked=false;Tasks.loot(scavenger,lm,0);ok(amount(scavenger,"minecraft:coal")==3&&barrel.getItem(0).isEmpty(),"container looting transfers actual contents once");ok(barrel.getItem(1).count==20,"leaves supplies it does not need");lm.work=box;Tasks.loot(scavenger,lm,20);ok(amount(scavenger,"minecraft:coal")==3,"reopening barrel does not regenerate loot");l.server.manager.claim=new FactionManager.Faction();ok(!Tasks.permitted(scavenger,box),"foreign claimed storage protected");
  World b=new World();AutoGunOperator cleaner=npc(b);Storage corpseInv=new Storage();corpseInv.setItem(0,new ItemStack("minecraft:iron_ingot",2));BlockPos body=new BlockPos(0,0,0);b.blocks.put(body,"minecraft:red_carpet");b.corpseData.corpses.put(body.asLong(),new dev.zomboid.remains.ZombieRemainsLoot.Record(corpseInv,"minecraft:red_carpet"));Social.Memory bm=Social.mem(cleaner);bm.scanIndex=433;Tasks.clean(cleaner,bm,0);ok(b.corpseData.corpses.isEmpty()&&amount(cleaner,"minecraft:iron_ingot")==2&&b.corpseData.dirty,"cleanup preserves all corpse contents before clearing record");
  b.blocks.put(body,"minecraft:red_carpet");b.corpseData.corpses.put(body.asLong(),new dev.zomboid.remains.ZombieRemainsLoot.Record(corpseInv,"minecraft:red_carpet"));cleaner.bag.clear();for(int i=0;i<47;i++)cleaner.bag.add(new ItemStack("minecraft:coal",64));bm.scanIndex=433;Tasks.clean(cleaner,bm,100);ok(b.corpseData.corpses.size()==1&&b.blocks.containsKey(body),"full inventory leaves body untouched");
  System.out.println("NPC_JOBS_AND_TREATMENT_CHECKS="+checks);
 }
}
